# Terraform: Refactor dev/prod into a `for_each` module

## Structure

```
infra/
├── modules/app/
│   ├── main.tf
│   ├── variables.tf
│   ├── outputs.tf
│   └── s3-replica.tf      # count-gated: prod only
├── terraform.tfvars
├── dev.tfvars
├── prod.tfvars
└── state-move.sh
```

## `modules/app/variables.tf`

```hcl
variable "env"               { type = string }
variable "region"            { type = string }
variable "node_count"        { type = number }
variable "node_instance"     { type = string }
variable "db_class"          { type = string }
variable "multi_az"          { type = bool }
variable "replicate_bucket"  { type = bool }
variable "oidc_trust_arns"   { type = list(string), default = [] }
```

## `modules/app/main.tf` (abridged to key resources)

```hcl
locals {
  name = "spine-${var.env}"
}

# --- EKS ---
module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 20.0"

  cluster_name    = local.name
  cluster_version = "1.30"

  vpc_id     = var.vpc_id
  subnet_ids = var.subnet_ids

  eks_managed_node_groups = {
    default = {
      desired_size   = var.node_count
      instance_types = [var.node_instance]
    }
  }
}

# --- S3 assets bucket (versioned, encrypted, no public access) ---
resource "aws_s3_bucket" "assets" {
  bucket = "${local.name}-assets"
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication — gated, prod only
resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.replicate_bucket ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  depends_on = [aws_s3_bucket_versioning.assets]

  role   = aws_iam_role.assets_replication[0].arn
  rule {
    id     = "all"
    status = "Enabled"
    filter {}
    destination {
      bucket        = aws_s3_bucket.assets_replica[0].arn
      storage_class = "STANDARD_IA"
    }
  }
}

resource "aws_s3_bucket" "assets_replica" {
  count         = var.replicate_bucket ? 1 : 0
  bucket        = "${local.name}-assets-usw2"
  provider      = aws.west
}
# ... + versioning/encryption/public-access-block on replica bucket

# --- RDS ---
resource "aws_db_instance" "pg" {
  identifier             = local.name
  engine                 = "postgres"
  engine_version         = "16"
  instance_class         = var.db_class
  allocated_storage      = 20
  multi_az               = var.multi_az
  storage_encrypted      = true
  publicly_accessible    = false
  deletion_protection    = true
  backup_retention_period = 7

  username = "spine_admin"
  password = random_password.db.result

  skip_final_snapshot = false
  final_snapshot_name = "${local.name}-final"
}

resource "random_password" "db" {
  length  = 32
  special = false
}

# Secret via SOPS provider — never plaintext in Git or state-adjacent files
resource "sops_file" "db_secret_source" {
  source_file = "secrets/${var.env}.enc.yaml"
}

resource "kubernetes_secret" "db_conn" {
  metadata {
    name      = "spine-db-conn"
    namespace = "spine"
  }
  data = {
    url = "postgresql://spine_admin:${random_password.db.result}@${aws_db_instance.pg.endpoint}:5432/spine"
  }
}

# --- IAM: least privilege; OIDC trust in prod, programmatic keys in dev ---
data "aws_iam_policy_document" "trust" {
  count = length(var.oidc_trust_arns) > 0 ? 1 : 0
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = var.oidc_trust_arns
    }
  }
}

data "aws_iam_policy_document" "svc" {
  statement {
    actions   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*",
    ]
  }
  # No wildcards anywhere, including prod.
}

resource "aws_iam_role" "svc" {
  count              = length(var.oidc_trust_arns) > 0 ? 1 : 0
  name               = "${local.name}-svc-role"
  assume_role_policy = data.aws_iam_policy_document.trust[0].json
}

resource "aws_iam_role_policy" "svc" {
  count  = length(var.oidc_trust_arns) > 0 ? 1 : 0
  role   = aws_iam_role.svc[0].id
  policy = data.aws_iam_policy_document.svc.json
}

resource "aws_iam_user" "svc_dev" {
  count = length(var.oidc_trust_arns) > 0 ? 0 : 1
  name  = "${local.name}-svc-user"
}

resource "aws_iam_user_policy" "svc_dev" {
  count  = length(var.oidc_trust_arns) > 0 ? 0 : 1
  user   = aws_iam_user.svc_dev[0].name
  policy = data.aws_iam_policy_document.svc.json
}

# --- HTTPS: CloudFront + ACM in prod, internal ALB in dev ---
resource "aws_cloudfront_distribution" "cdn" {
  count   = var.exposure == "cloudfront" ? 1 : 0
  enabled = true
  viewer_certificate {
    acm_certificate_arn      = var.acm_cert_arn
    ssl_support_method       = "sni"
    minimum_protocol_version = "TLSv1.2_2021"
  }
  # 443-only origin behavior, no forced redirect on :80 listener
  dynamic "default_cache_behavior" { /* ... */ }
}

resource "aws_lb" "internal" {
  count      = var.exposure == "internal_alb" ? 1 : 0
  name       = local.name
  internal   = true
  subnets    = var.subnet_ids
}

resource "aws_lb_listener" "https" {
  count             = var.exposure == "internal_alb" ? 1 : 0
  load_balancer_arn = aws_lb.internal[0].arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = var.acm_cert_arn
  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.app[0].arn
  }
}
```

(Providers, VPC inputs, and target group elided for brevity.)

## Root module with `for_each`

```hcl
terraform {
  required_providers {
    aws  = { source = "hashicorp/aws", version = "~> 5.0" }
    sops = { source = "carlpett/sops", version = "~> 1.0" }
  }
}

provider "aws" {
  alias  = "west"
  region = "us-west-2"
}

locals {
  environments = {
    dev = {
      region           = "us-east-1"
      node_count       = 2
      node_instance    = "t3.medium"
      db_class         = "db.t3.micro"
      multi_az         = false
      replicate_bucket = false
      exposure         = "internal_alb"
      oidc_trust_arns  = []
    }
    prod = {
      region           = "eu-west-1"
      node_count       = 4
      node_instance    = "t3.large"
      db_class         = "db.t3.medium"
      multi_az         = true
      replicate_bucket = true
      exposure         = "cloudfront"
      oidc_trust_arns  = ["arn:aws:iam::123456789012:oidc-provider/oidc.eks.eu-west-1.amazonaws.com"]
    }
  }
}

provider "aws" {
  region = each.value.region
  for_each = local.environments
}

module "app" {
  source   = "./modules/app"
  for_each = local.environments

  providers = {
    aws      = aws[each.key]
    aws.west = aws.west
  }

  env              = each.key
  region           = each.value.region
  node_count       = each.value.node_count
  node_instance    = each.value.node_instance
  db_class         = each.value.db_class
  multi_az         = each.value.multi_az
  replicate_bucket = each.value.replicate_bucket
  exposure         = each.value.exposure
  oidc_trust_arns  = each.value.oidc_trust_arns
}
```

Note: multiple same-alias providers require **Terraform ≥ 1.10** (`for_each` on provider blocks). On older versions use the module's `providers` map pointing at two aliased root providers instead.

Alternatively drive the env maps from `-var-file=dev.tfvars` / `prod.tfvars`, matching the canonical scenario.

## Zero-diff state migration

If previously there were separate working directories (or separate `dev`/`prod` resource blocks being unified), migrate addresses before the first plan:

```bash
#!/usr/bin/env bash
set -euo pipefail
# Run once from the new single-state root before `terraform plan`.
# Assumes old resources were named like this:

terraform init

for env in dev prod; do
  terraform state mv \
    -state-out="terraform-$env.tfstate-old" \
    aws_module.$env.aws_s3_bucket.assets \
    module.app["$env"].aws_s3_bucket.assets 2>/dev/null || true
done
```

Because old states lived in **separate** workspaces/states (different regions), the cleanest path is one merged state per move:

```bash
# 1. Snapshot both old states
cp terraform-dev.tfstate.d/dev/default.tfstate  backup-dev.tfstate
cp terraform-prod.tfstate.d/prod/default.tfstate backup-prod.tfstate

# 2. Move prod resources into combined state
terraform state push --   # see steps below

# Selectively import/move:
terraform state mv -state=backup-prod.tfstate \
  -state-out=terraform.tfstate \
  aws_db_instance.pg 'module.app["prod"].aws_db_instance.pg'

# 3. Repeat for every top-level address × both environments,
#    then verify:
terraform plan   # expect: No changes.

terraform plan -target='module.app["prod"]'   # also No changes.
```

If old and new *configurations* differ (e.g., decomposed EKS module replacing inline `aws_eks_cluster`), use targeted `moved` blocks inside `modules/app/main.tf` where addresses are consistent across environments:

```hcl
moved {
  from = aws_eks_cluster.this
  to   = module.eks.cluster
}
```

**Verification checklist before merge:**
1. `terraform state list | wc -l` matches pre/post resource counts
2. `terraform plan` → `No changes.` per environment (`-target='module.app["dev"]'` and `["prod"]` individually)
3. Changing any prod entry (e.g., `node_count`) plans changes only under `module.app["prod"]`
4. SOPS secret file still resolves; no plaintext DB password appears in state diff beyond the existing pattern
